-- Canonical star schema for the Danish health-care footprint, reference year 2022.
-- Generated by analysis.build_star_schema; this DDL is the contract the CSVs satisfy.
-- Types are PostgreSQL; they adapt unchanged to DuckDB, and with minor edits to
-- Fabric/Snowflake.
--
-- Load order matters: dimensions first, then facts, or the foreign keys fail.
--
-- Storage: every dimension, and every fact of at most 50,000 rows, is a CSV of
-- the same name in this directory; the larger facts are Parquet (pyarrow,
-- snappy), one file per fact. The five facts that predate that rule stay CSV.
-- The columns and types below are the contract either format satisfies.

-- ============================================================ DIMENSIONS

-- One row per model RUN the study reports: a distinct solve, whose reference
-- year, background vintage or sector boundary differs from the others and whose
-- outputs live in their own folder (source_folder). The configured run is
-- model_id 1. Variations computed WITHIN a run -- the capital treatment, the GWP
-- vintage, the characterisation method, the mitigation lever -- are their own
-- dimensions rather than model rows: folding them in here would need a row per
-- crossing, most of which no run ever produced, and would let a fact point at a
-- configuration that was never solved.
CREATE TABLE dim_model (
    model_id                 INTEGER      PRIMARY KEY,
    model_label              VARCHAR(300) NOT NULL,
    background_year          VARCHAR(30)  NOT NULL,
    analysis_year            INTEGER      NOT NULL,
    mrio                     VARCHAR(100) NOT NULL,
    danish_block_correction  VARCHAR(200),
    gwp_vintage              VARCHAR(30)  NOT NULL,
    scope_boundary           VARCHAR(60)  NOT NULL,
    capital                  VARCHAR(60)  NOT NULL,
    is_headline              BOOLEAN      NOT NULL,   -- the configured run
    source_folder            VARCHAR(120) NOT NULL,   -- where this run's tables are
    note                     TEXT
);

CREATE TABLE dim_region (
    region_id      INTEGER      PRIMARY KEY,
    region_code    VARCHAR(40)  NOT NULL UNIQUE,  -- ISO3, or the region name where no ISO3 exists
    region_name    VARCHAR(200) NOT NULL,
    world_region   VARCHAR(60)  NOT NULL,
    -- 'MRIO region' | 'truncation remainder'. fact_footprint_bilateral is
    -- thresholded at 99.5 % coverage and puts the tail on one
    -- BELOW_THRESHOLD_REMAINDER member, which is how it still reproduces its own
    -- total. Filter on region_type when a query needs real geography.
    region_type    VARCHAR(30)  NOT NULL,
    is_row_region  BOOLEAN      NOT NULL,
    is_domestic    BOOLEAN      NOT NULL
);

CREATE TABLE dim_industry_group (
    industry_group_id   INTEGER      PRIMARY KEY,
    industry_group_name VARCHAR(120) NOT NULL UNIQUE
);

CREATE TABLE dim_industry (
    industry_id       INTEGER      PRIMARY KEY,
    industry_code     VARCHAR(40)  NOT NULL UNIQUE,  -- EXIOBASE code, no A_ / C_ prefix
    industry_name     VARCHAR(300) NOT NULL,
    industry_group_id INTEGER      NOT NULL REFERENCES dim_industry_group (industry_group_id),
    -- 'MRIO industry' | 'bottom-up item' | 'truncation remainder'
    industry_type         VARCHAR(30)  NOT NULL,
    isic_rev3_division    VARCHAR(10),    -- EXIOBASE developers' ISIC Rev.3 concordance
    isic_rev3_description VARCHAR(300),
    technology_group      VARCHAR(60)     -- manufacturing divisions 15-37 only
);

CREATE TABLE dim_indicator (
    indicator_id   INTEGER      PRIMARY KEY,
    indicator_code VARCHAR(80)  NOT NULL UNIQUE,
    unit           VARCHAR(40)  NOT NULL
);

CREATE TABLE dim_scope (
    scope_id   INTEGER     PRIMARY KEY,
    scope_name VARCHAR(40) NOT NULL UNIQUE
);

CREATE TABLE dim_demand_component (
    demand_component_id   INTEGER     PRIMARY KEY,
    demand_component_name VARCHAR(80) NOT NULL UNIQUE
);

CREATE TABLE dim_health_function (
    health_function_id   INTEGER      PRIMARY KEY,
    health_function_name VARCHAR(120) NOT NULL UNIQUE
);


CREATE TABLE dim_scope_component (
    scope_component_id    INTEGER      PRIMARY KEY,
    component_code        VARCHAR(40)  NOT NULL UNIQUE,
    component_name        VARCHAR(120) NOT NULL,
    -- 'addend' | 'subtotal' | 'grand total'. The GHG-Protocol ladder carries its
    -- own subtotals, so SUM(value) over fact_scope_component double counts:
    -- filter to component_role = 'addend' for a partition.
    component_role        VARCHAR(20)  NOT NULL,
    parent_component_code VARCHAR(40)
);

-- One row per modelled mitigation VARIANT, not per lever: scenario_code B1
-- covers two grid pathways at two target years and P2 three delivery shares, so
-- (scenario_code, scenario_label, ambition) is the natural key. k_t, k_p and k_a
-- are the change coefficients (semicolon-separated for the combined scenarios).
CREATE TABLE dim_scenario (
    scenario_id              INTEGER      PRIMARY KEY,
    scenario_code            VARCHAR(20)  NOT NULL,
    scenario_label           VARCHAR(200) NOT NULL,
    ambition                 VARCHAR(120) NOT NULL,
    scenario_kind            VARCHAR(40)  NOT NULL,  -- background pathway | intervention | combined
    k_t                      VARCHAR(200),           -- technical change coefficient
    k_p                      VARCHAR(200),           -- penetration coefficient
    k_a                      VARCHAR(200),           -- applied coefficient, k_t * k_p
    edited_objects           VARCHAR(40),            -- A | B | y | bottom_up
    rebound                  BOOLEAN      NOT NULL,
    unbalanced_pct_of_output DOUBLE PRECISION,
    ambition_basis           TEXT,
    source                   TEXT,
    note                     TEXT,
    in_combined              BOOLEAN      NOT NULL,  -- a lever of the C1 combined scenario
    UNIQUE (scenario_code, scenario_label, ambition)
);

CREATE TABLE dim_production_layer (
    production_layer_id INTEGER      PRIMARY KEY,
    layer_code          VARCHAR(10)  NOT NULL UNIQUE,  -- '0'..'20', '>20'
    layer_number        INTEGER,                       -- NULL for the residual tail
    layer_name          VARCHAR(60)  NOT NULL,
    is_residual         BOOLEAN      NOT NULL,
    -- The residual tail is reported as an indicator total only. It equals the
    -- footprint less the resolved layers, so it stays derivable.
    has_node_detail     BOOLEAN      NOT NULL
);

-- Impact categories across every characterisation method present, which is what
-- lets the DESIRE set and IMPACT World+ share one fact table. quality_flag
-- carries the method's own verdict on a category; anything but 'ok' should be
-- excluded before a category is reported.
CREATE TABLE dim_impact_category (
    impact_category_id INTEGER      PRIMARY KEY,
    method             VARCHAR(120) NOT NULL,
    category_code      VARCHAR(200) NOT NULL,
    unit               VARCHAR(60)  NOT NULL,
    quality_flag       VARCHAR(60)  NOT NULL,
    UNIQUE (method, category_code)
);

CREATE TABLE dim_capital_treatment (
    capital_treatment_id INTEGER      PRIMARY KEY,
    treatment_code       VARCHAR(80)  NOT NULL UNIQUE,
    treatment_name       VARCHAR(200) NOT NULL,
    capital_included     BOOLEAN      NOT NULL,
    -- Two modules produce endogenised capital, on the GFCF ladder and on the
    -- published capital-use matrices, and they do not agree. They are separate
    -- members so that the disagreement is visible rather than averaged away.
    produced_by          VARCHAR(80)  NOT NULL
);

CREATE TABLE dim_substance (
    substance_id   INTEGER     PRIMARY KEY,
    substance_code VARCHAR(60) NOT NULL UNIQUE,
    base_unit      VARCHAR(20) NOT NULL,
    gwp100         DOUBLE PRECISION,           -- NULL where not restatable
    gwp_vintage    VARCHAR(30) NOT NULL,
    -- EXIOBASE supplies HFC and PFC already aggregated in CO2-equivalent, so
    -- their vintage is unknowable from the satellite account and they carry no
    -- factor. The flag says so instead of leaving a bare NULL to be guessed at.
    is_restatable  BOOLEAN     NOT NULL
);

CREATE TABLE dim_gwp_vintage (
    gwp_vintage_id   INTEGER     PRIMARY KEY,
    vintage_code     VARCHAR(30) NOT NULL UNIQUE,  -- 'IPCC AR6 (2021)'
    is_study_default BOOLEAN     NOT NULL
);

-- ================================================================= FACTS

-- Grain: model x indicator x demand component x producing region x producing industry.
CREATE TABLE fact_footprint_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    demand_component_id   INTEGER NOT NULL REFERENCES dim_demand_component (demand_component_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, demand_component_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x indicator x demand component x purchased region x purchased industry.
-- NOT interchangeable with fact_footprint_node: that one says where pressure ARISES,
-- this one says which purchase DRIVES it. They are marginals of the same table and
-- must never be summed together.
CREATE TABLE fact_footprint_product (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    demand_component_id   INTEGER NOT NULL REFERENCES dim_demand_component (demand_component_id),
    purchased_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    purchased_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, demand_component_id,
                 purchased_region_id, purchased_industry_id)
);

-- Grain: model x indicator x scope x producing region x producing industry.
CREATE TABLE fact_scope_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    scope_id              INTEGER NOT NULL REFERENCES dim_scope (scope_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, scope_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x indicator. Carried with every result set so a health share of the
-- national footprint can always be formed without leaving the model.
CREATE TABLE fact_national_total (
    model_id                   INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id               INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    national_footprint         DOUBLE PRECISION NOT NULL,
    national_supply_chain      DOUBLE PRECISION,
    national_direct_households DOUBLE PRECISION,
    healthcare_footprint_mrio  DOUBLE PRECISION,
    healthcare_share_pct       DOUBLE PRECISION,
    PRIMARY KEY (model_id, indicator_id)
);

-- Grain: model x indicator x health function (SHA).
CREATE TABLE fact_health_function (
    model_id           INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id       INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    health_function_id INTEGER NOT NULL REFERENCES dim_health_function (health_function_id),
    value              DOUBLE PRECISION NOT NULL,
    expenditure_meur   DOUBLE PRECISION,
    intensity_per_meur DOUBLE PRECISION,
    PRIMARY KEY (model_id, indicator_id, health_function_id)
);

-- Grain: model x indicator x demand component x producing node x purchased node.
-- THE PRIMARY footprint fact. fact_footprint_node and fact_footprint_product are
-- its two marginals and are kept only because most queries want them; the build
-- asserts that summing this over either margin reproduces the corresponding one.
-- Thresholded at 99.5 % coverage per indicator and demand component, with the
-- tail on one row whose producing and purchased keys are both the
-- BELOW_THRESHOLD_REMAINDER member, so the total is exact and the truncation is
-- visible. Stored as Parquet.
CREATE TABLE fact_footprint_bilateral (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    demand_component_id   INTEGER NOT NULL REFERENCES dim_demand_component (demand_component_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    purchased_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    purchased_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, demand_component_id,
                 producing_region_id, producing_industry_id,
                 purchased_region_id, purchased_industry_id)
);

-- Grain: model x demand component x purchased region x purchased industry.
-- The demand vector y_H the footprint is driven by, at the resolution it is
-- built at. Basic prices, M.EUR.
CREATE TABLE fact_health_expenditure (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    demand_component_id   INTEGER NOT NULL REFERENCES dim_demand_component (demand_component_id),
    purchased_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    purchased_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    expenditure_meur      DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, demand_component_id, purchased_region_id,
                 purchased_industry_id)
);

-- Grain: model x scenario x indicator x producing region x producing industry.
-- The counterfactual footprint. Every published scenario aggregate is derivable:
-- the scenario total is this summed over nodes, and the change against the
-- baseline is that less fact_footprint_node. Stored as Parquet.
CREATE TABLE fact_scenario_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    scenario_id           INTEGER NOT NULL REFERENCES dim_scenario (scenario_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, scenario_id, indicator_id, producing_region_id,
                 producing_industry_id)
);

-- Grain: model x indicator x production layer x producing region x producing
-- industry. Stored as Parquet.
CREATE TABLE fact_production_layer (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    production_layer_id   INTEGER NOT NULL REFERENCES dim_production_layer (production_layer_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, production_layer_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x impact category x producing region x producing industry.
-- Carries every characterisation method: the DESIRE set and, where that layer is
-- present, IMPACT World+. There is no indicator_id, because the category IS the
-- indicator here and it is method-specific; join dim_impact_category. Units
-- differ by category, so never sum across them. Stored as Parquet.
CREATE TABLE fact_impact_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    impact_category_id    INTEGER NOT NULL REFERENCES dim_impact_category (impact_category_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, impact_category_id, producing_region_id,
                 producing_industry_id)
);

-- Grain: model x indicator x health function x producing region x producing
-- industry. The primary health-function fact; fact_health_function is its margin
-- and is kept only for the expenditure and intensity it also carries. Built only
-- where 17_health_subsectors is present.
CREATE TABLE fact_health_function_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    health_function_id    INTEGER NOT NULL REFERENCES dim_health_function (health_function_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, health_function_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x capital treatment x indicator x producing region x producing
-- industry. Only the endogenised treatment is resolved to nodes.
CREATE TABLE fact_capital_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    capital_treatment_id  INTEGER NOT NULL REFERENCES dim_capital_treatment (capital_treatment_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, capital_treatment_id, indicator_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x capital treatment x indicator. The indicator total is the finest
-- grain the pipeline produces for the two treatments that have no node detail, so
-- they enter here rather than not at all.
CREATE TABLE fact_capital_scenario (
    model_id             INTEGER NOT NULL REFERENCES dim_model (model_id),
    capital_treatment_id INTEGER NOT NULL REFERENCES dim_capital_treatment (capital_treatment_id),
    indicator_id         INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    value                DOUBLE PRECISION NOT NULL,
    delta_vs_baseline    DOUBLE PRECISION,
    pct_vs_baseline      DOUBLE PRECISION,
    per_capita           DOUBLE PRECISION,
    PRIMARY KEY (model_id, capital_treatment_id, indicator_id)
);

-- Grain: model x substance. The climate footprint by greenhouse gas, which is
-- what makes the AR6 restatement auditable gas by gas.
CREATE TABLE fact_ghg_species (
    model_id     INTEGER NOT NULL REFERENCES dim_model (model_id),
    substance_id INTEGER NOT NULL REFERENCES dim_substance (substance_id),
    mass_kg      DOUBLE PRECISION,            -- NULL for the pre-aggregated HFC/PFC row
    gwp100       DOUBLE PRECISION,
    co2eq_kt     DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, substance_id)
);

-- Grain: model x GWP vintage x indicator. The climate characterisation
-- sensitivity, SAR to AR6, at the aggregate grain the sensitivity produces.
CREATE TABLE fact_gwp_vintage (
    model_id                 INTEGER NOT NULL REFERENCES dim_model (model_id),
    gwp_vintage_id           INTEGER NOT NULL REFERENCES dim_gwp_vintage (gwp_vintage_id),
    indicator_id             INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    healthcare_kt_co2eq      DOUBLE PRECISION NOT NULL,
    national_kt_co2eq        DOUBLE PRECISION,
    healthcare_share_pct     DOUBLE PRECISION,
    healthcare_t_per_capita  DOUBLE PRECISION,
    not_restatable_kt_co2eq  DOUBLE PRECISION,
    PRIMARY KEY (model_id, gwp_vintage_id, indicator_id)
);

-- Grain: model x indicator x scope component. The GHG-Protocol ladder for every
-- model run, which is what makes the 2019 run and the two sector-boundary runs
-- reachable at all: it is the only machine-readable output they share, and so is
-- the finest grain the pipeline produces for them. SUM over component_role =
-- 'addend' only; the ladder carries its own subtotals.
CREATE TABLE fact_scope_component (
    model_id           INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id       INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    scope_component_id INTEGER NOT NULL REFERENCES dim_scope_component (scope_component_id),
    value              DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, scope_component_id)
);

-- The Monte Carlo, at the grain it was actually simulated on. The uncertainty
-- layer published its summary and kept its detail in a NumPy array; this is
-- that array, keyed. Summing value over draw_group_id for one draw_id gives
-- that draw's total, and the published median, 95 % interval and coefficient
-- of variation are recovered from the distribution of those totals.
CREATE TABLE dim_draw_group (
    draw_group_id   INTEGER      PRIMARY KEY,
    draw_group_name VARCHAR(120) NOT NULL UNIQUE
);

CREATE TABLE fact_uncertainty_draw (
    model_id      INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id  INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    draw_id       INTEGER NOT NULL,
    draw_group_id INTEGER NOT NULL REFERENCES dim_draw_group (draw_group_id),
    value         DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, draw_id, draw_group_id)
);
